"""Dependency-free live view of recorded research activity and retrieval evidence."""

import json


def render_live_dashboard(token: str, initial_state: dict | None = None, *, offline=False) -> str:
    # The token arrives only in the private URL fragment, never in served HTML.
    bootstrap = {"state": initial_state}
    if offline:
        bootstrap["offline"] = True
    payload = json.dumps(bootstrap, ensure_ascii=False, allow_nan=False).replace(
        "&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
    return _HTML.replace("__BOOTSTRAP__", payload)


